import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Qvwhmedc.js";var i=JSON.parse(`{"title":"Setting Up The Project","description":"","frontmatter":{},"headers":[],"relativePath":"guides/contributing/setting-up-the-project.md","filePath":"guides/contributing/setting-up-the-project.md"}`),a={name:`guides/contributing/setting-up-the-project.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="setting-up-the-project" tabindex="-1">Setting Up The Project <a class="header-anchor" href="#setting-up-the-project" aria-label="Permalink to “Setting Up The Project”">​</a></h1><h2 id="setup-mise" tabindex="-1">Setup mise <a class="header-anchor" href="#setup-mise" aria-label="Permalink to “Setup mise”">​</a></h2><p>If you don&#39;t already have <a href="https://mise.jdx.dev/" target="_blank" rel="noreferrer">mise</a> you will want to begin by <a href="https://mise.jdx.dev/getting-started.html" target="_blank" rel="noreferrer">installing it</a> and adding its shell activation to your profile.</p><p>For package management, the project uses <a href="https://pnpm.io/" target="_blank" rel="noreferrer">PNPM</a>. The repo&#39;s <code>mise.toml</code> pins the <code>node</code>, <code>pnpm</code>, and <code>bun</code> versions we use; once mise is activated in your shell, run <code>mise install</code> from the project root to fetch them.</p><blockquote><p><strong>Note</strong> if you have previously installed pnpm, node, or bun globally via other means (including Volta or bun&#39;s own installer) you should uninstall them from all other locations first, as they can conflict with mise&#39;s shims.</p></blockquote><h2 id="install-certificate-packages" tabindex="-1">Install certificate packages <a class="header-anchor" href="#install-certificate-packages" aria-label="Permalink to “Install certificate packages”">​</a></h2><p>Install mkcert using homebrew on MacOS or Linux</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkcert</span></span></code></pre></div><p>can be done using Chocolatey, Scoop or MacPorts (User choice) checkout installation [doc][<a href="https://github.com/FiloSottile/mkcert?tab=readme-ov-file#installation" target="_blank" rel="noreferrer">https://github.com/FiloSottile/mkcert?tab=readme-ov-file#installation</a>]</p><p>For Firefox users, Mozilla NSS is also needed Using homebrew on MacOS</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nss</span></span></code></pre></div><p>Or apt on Linux</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libnss3-tools</span></span></code></pre></div><p>but can also be done using other methods.</p><h2 id="clone-the-repository" tabindex="-1">Clone the repository <a class="header-anchor" href="#clone-the-repository" aria-label="Permalink to “Clone the repository”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com:warp-drive-data/warp-drive.git</span></span></code></pre></div><h2 id="install-the-project-dependencies" tabindex="-1">Install the project dependencies <a class="header-anchor" href="#install-the-project-dependencies" aria-label="Permalink to “Install the project dependencies”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> warp-drive</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>Currently the install command is also what builds all of the individual packages in the monorepo and hardlinks them together, so if making changes to one package that need to be used by another you will need to rerun <code>pnpm install</code> for the changes to be picked up.</p><h2 id="create-certificates" tabindex="-1">Create certificates <a class="header-anchor" href="#create-certificates" aria-label="Permalink to “Create certificates”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dlx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @warp-drive/holodeck</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ensure-cert</span></span></code></pre></div><h2 id="building-the-project" tabindex="-1">Building the project <a class="header-anchor" href="#building-the-project" aria-label="Permalink to “Building the project”">​</a></h2><p>The project&#39;s packages will build whenever <code>pnpm install</code> is run. They can be rebuilt by running <code>pnpm prepare</code>.</p><p>Both <code>install</code> and <code>prepare</code> will ensure turbo cache is ignored so that pnpm will automatically update &quot;hardlinks&quot; for the build output files in the node_modules directory of the various other packages and test apps that depend upon the package.</p><p>However, this is pretty slow for development, so a fast albeit slightly manual approach is available for development by running the below commands in order:</p><p>From the project root:</p><ul><li>install: <code>pnpm install</code> - installs all dependencies and sets up initial hardlinks</li><li>start: <code>pnpm start</code> - starts the build for every public package in watch mode</li></ul><p>Then, from an individual test app:</p><ul><li><code>pnpm start</code> - starts the build for test assets in watch mode</li><li><code>pnpm test:start</code> - launches a test server (and by opens a browser window for debugging them)</li></ul><p>Because the project uses hardlinks, even though the packages are rebuilding, the test apps won&#39;t be able to see the results of the change in many scenarios unless the hardlinks are regenerated.</p><p>At anypoint, run <code>pnpm sync</code> from the root to regenerate the hardlinks. The test app server may pick up this change automatically, but if it does not saving any file (even without changing it) in the test app will trigger a rebuild.</p><h2 id="run-some-commands" tabindex="-1">Run some commands <a class="header-anchor" href="#run-some-commands" aria-label="Permalink to “Run some commands”">​</a></h2><p>Generally test and lint commands can be found in the <code>&quot;scripts&quot;</code> section of the root <code>package.json</code> manifest. Individual packages or test packages have additional commands in the <code>&quot;scripts&quot;</code> section of their own <code>package.json</code> manifest as well.</p><p>Any command in script can be run using <code>pnpm</code> from the directory of that manifest. For instance, to run linting from the root: <code>pnpm lint</code></p><p>Github Actions workflows will generally use these same commands.</p>`,35)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};